import{_ as n,o as i,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Zaman Eksplorasi Antar Bidang","description":"","frontmatter":{},"headers":[],"relativePath":"id/78-跨位面探索纪元.md","filePath":"id/78-跨位面探索纪元.md","lastUpdated":1789183869000}'),r={name:"id/78-跨位面探索纪元.md"};function s(d,a,l,k,o,u){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="zaman-eksplorasi-antar-bidang" tabindex="-1">Zaman Eksplorasi Antar Bidang <a class="header-anchor" href="#zaman-eksplorasi-antar-bidang" aria-label="Permalink to &quot;Zaman Eksplorasi Antar Bidang&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>78</td></tr><tr><td>Modul</td><td>Zaman Sejarah dan Peristiwa Penting</td></tr><tr><td>Kata Kunci Inti</td><td>Eksplorasi antar bidang, penemuan besar bidang, perjanjian arkeologi, observasi dulu baru intervensi, simbiosis antarbintang</td></tr></tbody></table><h2 id="_1-syarat-pembukaan-zaman-eksplorasi-antar-bidang" tabindex="-1">1. Syarat Pembukaan Zaman Eksplorasi Antar Bidang <a class="header-anchor" href="#_1-syarat-pembukaan-zaman-eksplorasi-antar-bidang" aria-label="Permalink to &quot;1. Syarat Pembukaan Zaman Eksplorasi Antar Bidang&quot;">​</a></h2><p>Zaman Eksplorasi Antar Bidang adalah zaman baru yang dibuka setelah pendirian Republik Semua Ras, sesuai dengan fase transisi dari &quot;evolusi kesadaran&quot; ke &quot;simbiosis antarbintang&quot; dalam jalur kenaikan dimensi empat tahap. Pembukaan zaman ini memerlukan kematangan simultan dari tiga syarat:</p><ul><li><strong>Syarat Teknologi</strong>: Teknologi hukum ruang mencapai alam &quot;sumber ruang&quot;, pembukaan stabil saluran antar bidang menjadi mungkin; teknologi cermin salinan dan ruang terisolasi matang, memberikan jaminan teknologi untuk eksplorasi rendah polusi</li><li><strong>Syarat Institusi</strong>: Republik Semua Ras didirikan, kebijakan eksplorasi antar bidang yang terpadu dan perjanjian arkeologi selesai disusun</li><li><strong>Syarat Motivasi</strong>: Pekerjaan kenaikan dimensi bidang yang diketahui berlangsung teratur, peradaban memiliki kemampuan dan keinginan untuk memperluas ke bidang yang tidak diketahui</li></ul><p>Ketika ketiga syarat ini matang secara bersamaan, Republik Semua Ras secara resmi mengumumkan peluncuran &quot;Rencana Eksplorasi Besar&quot;, dan Zaman Eksplorasi Antar Bidang dimulai dengan demikian.</p><h2 id="_2-prinsip-dasar-eksplorasi-antar-bidang" tabindex="-1">2. Prinsip Dasar Eksplorasi Antar Bidang <a class="header-anchor" href="#_2-prinsip-dasar-eksplorasi-antar-bidang" aria-label="Permalink to &quot;2. Prinsip Dasar Eksplorasi Antar Bidang&quot;">​</a></h2><p>Eksplorasi antar bidang secara ketat mengikuti prinsip-prinsip dasar berikut, yang ditulis dalam &quot;Hukum Dasar Eksplorasi Antar Bidang&quot;:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Makna</th></tr></thead><tbody><tr><td>Observasi dulu baru intervensi terbatas</td><td>Untuk bidang yang tidak diketahui, pertama lakukan observasi pasif, baru setelah pemahaman yang cukup lakukan kontak dan intervensi terbatas</td></tr><tr><td>Eksplorasi rendah polusi</td><td>Menggunakan rencana arkeologi cermin salinan + ruang terisolasi, hanya mengirimkan pengetahuan kembali, tidak membawa materi dan kehidupan masuk atau keluar</td></tr><tr><td>Perlindungan peradaban asli</td><td>Untuk bidang dengan peradaban asli, menghormati hak perkembangan otonom mereka, tidak boleh memaksakan sistem simbiosis</td></tr><tr><td>Berbagi sumber daya</td><td>Pengetahuan dan sumber daya yang ditemukan dalam eksplorasi menjadi milik seluruh peradaban, tidak ada organisasi yang boleh memonopoli hasil eksplorasi</td></tr><tr><td>Keamanan diutamakan</td><td>Keamanan dalam proses eksplorasi selalu ditempatkan di posisi pertama, eksplorasi bidang berisiko tinggi harus melalui evaluasi risiko yang ketat</td></tr></tbody></table><h2 id="_3-sarana-teknologi-eksplorasi" tabindex="-1">3. Sarana Teknologi Eksplorasi <a class="header-anchor" href="#_3-sarana-teknologi-eksplorasi" aria-label="Permalink to &quot;3. Sarana Teknologi Eksplorasi&quot;">​</a></h2><p>Eksplorasi antar bidang menggunakan secara terintegrasi berbagai teknologi inti peradaban simbiosis:</p><ol><li><strong>Teknologi Pemindaian Bidang</strong>: Pemindaian bidang jarak jauh berdasarkan modul persepsi hukum ruang, dapat memperoleh informasi dasar (struktur ruang, tingkat energi, tanda-tanda kehidupan, dll.) tanpa kontak dengan bidang target</li><li><strong>Rencana Arkeologi Cermin Salinan</strong>: Melakukan salinan cermin presisi tinggi dari bidang target, melakukan penelitian mendalam pada salinan cermin di ruang terisolasi, hanya mengirimkan pengetahuan kembali</li><li><strong>Probe Komunikasi Antar Bidang</strong>: Perangkat komunikasi hukum mini, dapat dikirim ke bidang target untuk observasi jarak dekat, data dikirim kembali secara real-time melalui jaringan komunikasi antar bidang</li><li><strong>Persepsi Domain Kesadaran</strong>: Kultivator tingkat tinggi melakukan persepsi jarak jauh terhadap bidang target melalui domain kesadaran, memperoleh informasi tingkat kesadaran yang tidak dapat ditangkap oleh teknologi pemindaian</li><li><strong>Penyebaran Neo Jarak Jauh</strong>: Untuk bidang dengan tingkat keamanan tinggi, dapat menyebarkan neo sementara dari jarak jauh, membangun saluran koneksi yang stabil</li></ol><h2 id="_4-organisasi-dan-pelaksanaan-eksplorasi" tabindex="-1">4. Organisasi dan Pelaksanaan Eksplorasi <a class="header-anchor" href="#_4-organisasi-dan-pelaksanaan-eksplorasi" aria-label="Permalink to &quot;4. Organisasi dan Pelaksanaan Eksplorasi&quot;">​</a></h2><p>Eksplorasi antar bidang diorganisir dan dilaksanakan secara terpadu oleh &quot;Biro Eksplorasi Antar Bidang&quot; Republik Semua Ras, mengadopsi model &quot;eksplorasi bertingkat&quot;:</p><table tabindex="0"><thead><tr><th>Tingkat Eksplorasi</th><th>Jenis Target</th><th>Cara Eksplorasi</th><th>Konfigurasi Personel</th></tr></thead><tbody><tr><td>Eksplorasi Tingkat 1</td><td>Bidang tandus tanpa kehidupan</td><td>Pemindaian jarak jauh + penelitian cermin salinan</td><td>Utamanya tim teknologi</td></tr><tr><td>Eksplorasi Tingkat 2</td><td>Bidang dengan kehidupan rendah</td><td>Arkeologi cermin salinan + investigasi lapangan terbatas</td><td>Tim teknologi + ahli biologi</td></tr><tr><td>Eksplorasi Tingkat 3</td><td>Bidang dengan peradaban asli</td><td>Observasi dulu baru kontak, mematuhi protokol kontak secara ketat</td><td>Tim lengkap + diplomat + pengamat etika</td></tr><tr><td>Eksplorasi Tingkat 4</td><td>Bidang berisiko tinggi / tidak diketahui</td><td>Hanya penelitian simulasi di ruang terisolasi, kontak lapangan dilarang</td><td>Tim keamanan tingkat tertinggi</td></tr></tbody></table><p>Setiap proyek eksplorasi harus melalui proses lengkap &quot;pengajuan eksplorasi — evaluasi risiko — tinjauan etika — persetujuan pelaksanaan — pemantauan proses — berbagi hasil&quot;.</p><h2 id="_5-penemuan-penting-zaman-eksplorasi" tabindex="-1">5. Penemuan Penting Zaman Eksplorasi <a class="header-anchor" href="#_5-penemuan-penting-zaman-eksplorasi" aria-label="Permalink to &quot;5. Penemuan Penting Zaman Eksplorasi&quot;">​</a></h2><p>Setelah pembukaan Zaman Eksplorasi Antar Bidang, peradaban simbiosis membuat serangkaian penemuan penting:</p><ul><li><strong>Penemuan ras baru</strong>: Menemukan sejumlah besar ras cerdas yang sebelumnya tidak diketahui di bidang yang tidak diketahui, silsilah semua ras diperluas secara signifikan. Ras-ras baru ini secara bertahap bergabung dengan Republik Semua Ras setelah pilihan sukarela</li><li><strong>Penemuan hukum baru</strong>: Terdapat perbedaan dalam struktur hukum bidang yang berbeda, berbagai varian hukum baru ditemukan dalam eksplorasi, memperkaya dasar teoretis dari tiga ratus sistem kultivasi</li><li><strong>Reruntuhan peradaban kuno</strong>: Menemukan reruntuhan beberapa peradaban yang punah dari zaman pra-neo, memperoleh sejumlah besar pengetahuan sejarah berharga melalui arkeologi cermin salinan</li><li><strong>Peradaban simbiosis bidang lain</strong>: Menemukan di beberapa bidang peradaban asli yang secara mandiri mengembangkan konsep simbiosis, membentuk resonansi pemikiran melintasi ruang dengan peradaban simbiosis neo</li><li><strong>Eksplorasi batas alam semesta</strong>: Eksplorasi secara bertahap menyentuh batas yang diketahui dari Hengyuanzhou, pemahaman tentang struktur keseluruhan alam semesta terus mendalam</li></ul><h2 id="_6-tantangan-dan-refleksi-dalam-eksplorasi" tabindex="-1">6. Tantangan dan Refleksi dalam Eksplorasi <a class="header-anchor" href="#_6-tantangan-dan-refleksi-dalam-eksplorasi" aria-label="Permalink to &quot;6. Tantangan dan Refleksi dalam Eksplorasi&quot;">​</a></h2><p>Eksplorasi antar bidang tidak selalu berjalan mulus, dalam prosesnya juga menghadapi tantangan:</p><ul><li><strong>Konflik budaya</strong>: Dalam kontak dengan peradaban asli, terjadi kesalahpahaman dan konflik budaya, yang mendorong perbaikan berkelanjutan dari protokol kontak</li><li><strong>Kontroversi etika eksplorasi</strong>: Terdapat perdebatan etika yang berkelanjutan tentang &quot;apakah harus secara aktif menghubungi peradaban asli&quot;, akhirnya membentuk konsensus &quot;tidak aktif, tidak menghindar, menghormati pilihan&quot;</li><li><strong>Kecelakaan keamanan</strong>: Terjadi kecelakaan kerusakan penghalang ruang terisolasi dalam eksplorasi bidang berisiko tinggi; meskipun tidak menyebabkan konsekuensi serius, tetapi mendorong peningkatan lebih lanjut dari standar keamanan</li><li><strong>Alokasi sumber daya</strong>: Eksplorasi skala besar memerlukan konsumsi sumber daya dalam jumlah besar, keseimbangan antara investasi eksplorasi dan investasi kesejahteraan lokal menjadi fokus perdebatan politik</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Zaman Eksplorasi Antar Bidang adalah &quot;Zaman Penjelajahan Besar&quot; dari peradaban simbiosis jangkar. Ia memperluas cakrawala peradaban dari bidang yang diketahui ke seluruh alam semesta, sambil menemukan dunia baru juga memperdalam pemahaman tentang diri sendiri. Rencana eksplorasi rendah polusi cermin salinan + ruang terisolasi membuat eksplorasi peradaban simbiosis berbeda dari semua ekspansi kolonial predator dalam sejarah — yang kita bawa bukan penaklukan dan penjarahan, melainkan rasa hormat dan pengetahuan; yang kita bawa kembali bukan sumber daya dan budak, melainkan pemahaman dan kebijaksanaan. Ketika bidang yang dieksplorasi cukup banyak dan jaringan neo cukup padat, pintu zaman simbiosis antarbintang akan terbuka perlahan.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>77-Pendirian Republik Semua Ras</li><li>79-Prospek Zaman Simbiosis Antarbintang</li><li>84-Garis Besar Perjanjian Arkeologi</li></ul>',26)])])}const p=n(r,[["render",s]]);export{g as __pageData,p as default};
